export type DynamicBadgeCounts = Partial<Record<DynamicBadgeKey, number>>

/** Aria label text for the overdue count badge. */
function overdueAriaLabel(overdueCount: number, totalCount: number): string {
  return overdueCount > 0
    ? `${overdueCount} overdue items (${totalCount} total)`
    : `${totalCount} items`
}

