{/* Overdue-count badge — gray pill (no urgency) or Rust pill (overdue > 0).
    Rust bg uses --color-destructive token. Bone text matches badge pattern.
    Shows overdue count when urgent; total count otherwise. */}
{showOverdueBadge && (
  <span
    className={cn(
      'ml-auto inline-flex min-w-[20px] items-center justify-center rounded-full px-1.5 py-0.5 text-[10px] font-semibold tabular-nums group-data-[collapsible=icon]:hidden',
      overdueIsUrgent
        ? 'bg-destructive text-destructive-foreground'
        : 'bg-muted text-muted-foreground',
    )}
    aria-label={overdueAriaLabel(overdueCount, dynamicCount)}
  >
    {formatCount(overdueIsUrgent ? overdueCount : dynamicCount)}
  </span>
)}

