  (inboxUnreadConvsRes.count ?? 0)

// Overdue urgency: union of deposit-unpaid + consent-unsigned bookings within 24h.
// These two queries may overlap (same booking can be both deposit-unpaid AND consent-unsigned).
// We cap at inboxCount so the overdue count never exceeds total inbox count.
const inboxOverdueCount = Math.min(
  (overdueDepositRes.count ?? 0) + (overdueConsentRes.count ?? 0),
  inboxCount,
)

